// Aseprite's built-in command catalog (generated by agent/tools/gen_commands.py).
import commandCatalog from "./commands.json" with { type: "json" };

export interface CommandParam {
  name: string;
  type: string;
  default?: string;
  values?: string[];
  aliases?: string[];
}
export interface CommandInfo {
  name: string;
  title: string;
  params: CommandParam[];
}

export const COMMANDS = commandCatalog as CommandInfo[];
const BY_NAME = new Map(COMMANDS.map((c) => [c.name.toLowerCase(), c]));

export function findCommand(name: string): CommandInfo | undefined {
  return BY_NAME.get(name.toLowerCase());
}

/** Command names that look like a misspelling of `name`. */
export function suggestCommands(name: string, limit = 8): string[] {
  const key = name.toLowerCase().slice(0, 5);
  return COMMANDS.filter((c) => c.name.toLowerCase().includes(key)).slice(0, limit).map((c) => c.name);
}

export function filterCommands(filter?: string): CommandInfo[] {
  const f = filter?.toLowerCase();
  return COMMANDS.filter((c) => !f || c.name.toLowerCase().includes(f) || c.title.toLowerCase().includes(f));
}

/**
 * Params as the extension expects them: color-typed params given as
 * "#rrggbb" strings are marked so Lua builds Color objects.
 */
export function toWireParams(info: CommandInfo, params: Record<string, unknown> = {}): Record<string, unknown> {
  const colorParams = new Set(info.params.filter((p) => p.type === "color").map((p) => p.name));
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(params)) out[k] = colorParams.has(k) && typeof v === "string" ? { __color: v } : v;
  return out;
}

export function describeCommand(c: CommandInfo): string {
  const params = c.params
    .filter((p) => p.name !== "ui" && !p.name.startsWith("_"))
    .map((p) => {
      let s = `${p.name}: ${p.type}`;
      if (p.values) s += ` (${p.values.join("|")})`;
      if (p.default) s += ` = ${p.default}`;
      return s;
    });
  return `${c.name} — ${c.title || "(no title)"}${params.length ? `\n    ${params.join("\n    ")}` : ""}`;
}
